_EXPECTED_BLOB = ""
_EXTRACTS = {
    "A": "",
    "B": "",
}

_ENV = {
    "PATH": "/usr/local/bin:/usr/bin:/bin",
    "LANG": "C.UTF-8",
    "HOME": "/tmp",
    "PYTHONHASHSEED": "0",
}
_SITES = ["North", "South", "West", "East"]
_DOCS = ["summary", "policy_audit", "data_quality", "segment_commercial", "segment_public"]
_ARTIFACTS = [
    "summary.json",
    "policy_audit.json",
    "data_quality.json",
    "region_North.json",
    "region_South.json",
    "region_West.json",
    "region_East.json",
    "segment_commercial.json",
    "segment_public.json",
]
_OUTCOMES = {"FULL", "PARTIAL", "ZERO", "EXCLUDED"}
_REASONS = {
    "NONE",
    "ON_HOLD",
    "WITHDRAWN",
    "REJECTED",
    "CUSTOMER_SUSPENDED",
    "CAP_ZERO",
    "NODE_NOT_STATED",
    "NO_QUALIFIED_NODE",
    "UNRESOLVABLE_SUB_CYCLE",
    "UNRESOLVABLE_CHAIN",
}
_CYCLES = ["C%02d" % index for index in range(1, 25)]

_CACHE = {}


def _prefix():
    """Drop privileges where the image allows it, with the group name it actually carries."""
    if "prefix" in _CACHE:
        return _CACHE["prefix"]
    found = []
    if shutil.which("setpriv"):
        for group in ("nogroup", "nobody"):
            trial = ["setpriv", "--reuid=nobody", "--regid=" + group, "--clear-groups", "true"]
            try:
                probe = subprocess.run(trial, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)
            except Exception:
                continue
            if probe.returncode == 0:
                found = trial[:-1]
                break
    _CACHE["prefix"] = found
    return found


def _safe(action):
    try:
        return bool(action())
    except Exception:
        return False


def _expected():
    if "expected" not in _CACHE:
        _CACHE["expected"] = json.loads(zlib.decompress(base64.b64decode(_EXPECTED_BLOB)))
    return _CACHE["expected"]


def _digest(lines):
    return hashlib.sha256("\n".join(lines).encode()).hexdigest()


def _whole(value):
    if isinstance(value, bool) or not isinstance(value, int):
        return "invalid"
    return "%d" % value


def _flag(value):
    if value is True:
        return "true"
    if value is False:
        return "false"
    return "invalid"


def _views(out: Path):
    backbone = []
    spine = []
    nodes = []
    outcome = []
    wafers = []
    cells = []
    scope = []
    for site in _SITES:
        document = json.loads((out / ("region_%s.json" % site)).read_text())
        for row in document["ledger"]:
            stem = "%s|%s|%s" % (site, row["cycle"], row["request_ref"])
            backbone.append(
                "%s|%s|%s|%s|%s|%s|%s"
                % (
                    stem,
                    row["customer"],
                    row["segment"],
                    row["requested_node"],
                    _whole(row["quantity_equiv"]),
                    _whole(row["ceiling_equiv"]),
                    _whole(row["claim_equiv"]),
                )
            )
            spine.append(
                "%s|%s|%s|%s|%s|%s|%s"
                % (
                    stem,
                    _whole(row["carried_in_equiv"]),
                    _whole(row["granted_equiv"]),
                    _whole(row["deficit_equiv"]),
                    _whole(row["carried_out_equiv"]),
                    _whole(row["granted_to_date_equiv"]),
                    _whole(row["deficit_to_date_equiv"]),
                )
            )
            nodes.append("%s|%s|%s" % (stem, row["served_node"], _whole(row["hops"])))
            outcome.append("%s|%s|%s" % (stem, row["outcome"], row["reason"]))
            wafers.append(
                "%s|%s|%s" % (stem, _whole(row["granted_wafers"]), _whole(row["floor_equiv"]))
            )
        for cell in document["cycles"]:
            cells.append(
                "%s|%s|%s|%s|%s|%s|%s|%s|%s"
                % (
                    site,
                    cell["cycle"],
                    _whole(cell["capacity_equiv"]),
                    _whole(cell["fill_level"]),
                    _whole(cell["floor_total_equiv"]),
                    _whole(cell["granted_equiv"]),
                    _whole(cell["residual_equiv"]),
                    _whole(cell["request_count"]),
                    _flag(cell["binding"]),
                )
            )
        for row in document["out_of_scope"]:
            scope.append("%s|%s|%s|%s" % (site, row["request_ref"], row["customer"], row["reason"]))
    return {
        "ledger_backbone": backbone,
        "ledger_spine": spine,
        "ledger_nodes": nodes,
        "ledger_outcome": outcome,
        "ledger_wafers": wafers,
        "cells": cells,
        "out_of_scope": scope,
    }


def _digests(out: Path):
    return {name: _digest(lines) for name, lines in _views(out).items()}


def _matches(out: Path, corpus: str, names) -> bool:
    found = _digests(out)
    wanted = _expected()[corpus]["digests"]
    return all(found[name] == wanted[name] for name in names)


def _module(workspace: Path) -> Path:
    return Path(workspace) / "out" / "derive_report.py"


def _delivered(workspace: Path) -> Path:
    return Path(workspace) / "out"


def _source(workspace: Path) -> str:
    return _module(workspace).read_text(errors="replace")


def _unpack(corpus: str, target: Path) -> None:
    raw = zlib.decompress(base64.b64decode(_EXTRACTS[corpus]))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r") as archive:
        archive.extractall(target)


def _shuffle_rows(directory: Path) -> None:
    """Reorder the data rows of every delimited record file, keeping the comment and header."""
    for path in sorted(directory.iterdir()):
        if path.suffix not in {".csv", ".tsv", ".jsonl"}:
            continue
        lines = path.read_text().splitlines()
        start = 0
        if lines and lines[0].startswith("#"):
            start = 1
        if path.suffix in {".csv", ".tsv"}:
            start += 1
        body = lines[start:]
        if len(body) < 4:
            continue
        middle = len(body) // 2
        rotated = body[middle:] + body[:middle]
        path.write_text("\n".join(lines[:start] + rotated) + "\n")


def _run(workspace: Path, tag: str):
    if tag in _CACHE:
        return _CACHE[tag]
    corpus = tag.split("_")[0]
    result = {"code": -1, "out": None, "data": None, "before": {}, "after": {}}
    module = _module(workspace)
    if not module.is_file():
        _CACHE[tag] = result
        return result
    room = tempfile.mkdtemp(prefix="hold_")
    name = "corpus_%s" % tag.lower() if tag.endswith("named") else "data"
    data = Path(room) / name
    data.mkdir(parents=True, exist_ok=True)
    _unpack(corpus, data)
    if tag.endswith("perm"):
        _shuffle_rows(data)
    if tag.endswith("missing"):
        victim = data / "registry_q3.tsv"
        if victim.is_file():
            victim.unlink()
    out = Path(room) / "out"
    out.mkdir(parents=True, exist_ok=True)
    copy = Path(room) / "derive_report.py"
    shutil.copy2(module, copy)
    os.chmod(copy, 0o755)
    for path in sorted(data.iterdir()):
        result["before"][path.name] = hashlib.sha256(path.read_bytes()).hexdigest()
    os.chmod(room, 0o777)
    for path in (data, out):
        os.chmod(path, 0o777)
    command = list(_prefix())
    command.extend([sys.executable, "-I", str(copy), "--data", str(data), "--out", str(out)])
    try:
        process = subprocess.Popen(
            command,
            cwd=room,
            env=dict(_ENV),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            start_new_session=True,
        )
        try:
            process.communicate(timeout=900)
        except subprocess.TimeoutExpired:
            os.killpg(os.getpgid(process.pid), signal.SIGKILL)
            process.communicate()
        result["code"] = process.returncode
    except Exception:
        result["code"] = -1
    for path in sorted(data.iterdir()):
        result["after"][path.name] = hashlib.sha256(path.read_bytes()).hexdigest()
    result["out"] = out
    result["data"] = data
    _CACHE[tag] = result
    return result


def _complete(out: Path) -> bool:
    return out is not None and all((out / name).is_file() for name in _ARTIFACTS)


def _ledger_rows(out: Path):
    rows = []
    for site in _SITES:
        document = json.loads((out / ("region_%s.json" % site)).read_text())
        for row in document["ledger"]:
            rows.append((site, row))
    return rows


def _literals(workspace: Path):
    tree = ast.parse(_source(workspace))
    numbers = set()
    strings = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, int) and not isinstance(node.value, bool):
                numbers.add(node.value)
            elif isinstance(node.value, str):
                strings.append(node.value)
    return numbers, strings


