@criterion(description="The cross document identities hold on the delivered artifacts, with the region and segment grants agreeing, capacity equal to grant plus residual, claim equal to grant plus shortfall, and the running shortfall never falling.")
def cross_artifact_identity_triangle_holds(workspace: Path) -> bool:
    def body():
        out = _delivered(workspace)
        summary = json.loads((out / "summary.json").read_text())
        checks = summary["totals"]["identity_checks"]
        if any(checks[key] != 0 for key in checks):
            return False
        region_granted = 0
        capacity = 0
        residual = 0
        for site in _SITES:
            document = json.loads((out / ("region_%s.json" % site)).read_text())
            region_granted += sum(row["granted_equiv"] for row in document["ledger"])
            capacity += sum(cell["capacity_equiv"] for cell in document["cycles"])
            residual += sum(cell["residual_equiv"] for cell in document["cycles"])
            for cell in document["cycles"]:
                granted = sum(
                    row["granted_equiv"] for row in document["ledger"] if row["cycle"] == cell["cycle"]
                )
                if granted != cell["granted_equiv"]:
                    return False
                if cell["capacity_equiv"] != cell["granted_equiv"] + cell["residual_equiv"]:
                    return False
                if cell["binding"] != (cell["residual_equiv"] == 0):
                    return False
            seen = {}
            order = {cycle: index for index, cycle in enumerate(_CYCLES)}
            for row in sorted(document["ledger"], key=lambda item: order[item["cycle"]]):
                key = row["customer"]
                if row["deficit_to_date_equiv"] < seen.get(key, 0):
                    return False
                seen[key] = row["deficit_to_date_equiv"]
                if row["claim_equiv"] != row["granted_equiv"] + row["deficit_equiv"]:
                    return False
        segment_granted = 0
        for segment in ("commercial", "public"):
            document = json.loads((out / ("segment_%s.json" % segment)).read_text())
            segment_granted += document["totals"]["granted_equiv"]
        if region_granted != segment_granted:
            return False
        totals = summary["totals"]
        wanted = _expected()["shipped"]["scalars"]
        return (
            totals["granted_equiv"] == region_granted
            and totals["capacity_equiv"] == capacity
            and totals["residual_equiv"] == residual
            and totals["granted_equiv"] == wanted["granted_equiv"]
            and totals["capacity_equiv"] == wanted["capacity_equiv"]
        )

    return _safe(body)


